import {
  canonicalFacebookPostMediaId,
  facebookPostMediaIdCandidates,
} from "./facebookPostMediaId.ts";
import { assertEquals } from "https://deno.land/std@0.224.0/assert/mod.ts";

Deno.test("facebookPostMediaIdCandidates — full composite id", () => {
  const pageId = "106305844997969";
  const postId = "106305844997969_706511974987669";
  assertEquals(facebookPostMediaIdCandidates(postId, pageId).sort(), [
    "106305844997969_706511974987669",
    "706511974987669",
  ].sort());
});

Deno.test("facebookPostMediaIdCandidates — suffix-only webhook id", () => {
  const pageId = "106305844997969";
  const postId = "706511974987669";
  assertEquals(facebookPostMediaIdCandidates(postId, pageId).sort(), [
    "706511974987669",
    "106305844997969_706511974987669",
  ].sort());
});

Deno.test("canonicalFacebookPostMediaId — suffix to composite", () => {
  assertEquals(
    canonicalFacebookPostMediaId("706511974987669", "106305844997969"),
    "106305844997969_706511974987669",
  );
});

Deno.test("canonicalFacebookPostMediaId — already composite", () => {
  assertEquals(
    canonicalFacebookPostMediaId("106305844997969_706511974987669", "106305844997969"),
    "106305844997969_706511974987669",
  );
});

/** Facebook post IDs from Graph API use `{pageId}_{postId}`; feed webhooks may send either form. */
export function facebookPostMediaIdCandidates(
  postId: string,
  pageId: string,
): string[] {
  const trimmed = postId.trim();
  const page = pageId.trim();
  if (!trimmed) return [];

  const candidates = new Set<string>([trimmed]);
  if (!page) return [...candidates];

  if (trimmed.includes("_")) {
    const suffix = trimmed.split("_").pop()?.trim();
    if (suffix) candidates.add(suffix);
    if (!trimmed.startsWith(`${page}_`)) {
      candidates.add(`${page}_${trimmed}`);
    }
  } else {
    candidates.add(`${page}_${trimmed}`);
  }

  return [...candidates];
}

export function canonicalFacebookPostMediaId(postId: string, pageId: string): string {
  const trimmed = postId.trim();
  const page = pageId.trim();
  if (!trimmed) return trimmed;
  if (trimmed.includes("_")) return trimmed;
  return page ? `${page}_${trimmed}` : trimmed;
}

import {
  followStatusToLegacyBoolean,
  isConsentRequiredMetaError,
  resolveFollowStatus,
  type FollowCheckResult,
} from "./followCheckStatus.ts";

const META_GRAPH_VERSION = "v21.0";

/** @deprecated Prefer FollowCheckResult.status — kept for call sites that read isFollower. */
export type ParticipantProfile = FollowCheckResult;

export async function fetchParticipantFollowCheck(
  scopedUserId: string,
  accessToken: string,
  opts?: { messagingWindowOpen?: boolean },
): Promise<FollowCheckResult> {
  const fields = "username,name,is_user_follow_business";
  const url =
    `https://graph.facebook.com/${META_GRAPH_VERSION}/${encodeURIComponent(scopedUserId)}?fields=${fields}`;
  try {
    const res = await fetch(url, {
      headers: { Authorization: `Bearer ${accessToken}` },
    });
    const data = await res.json() as {
      username?: string;
      name?: string;
      is_user_follow_business?: boolean;
      error?: { message?: string; code?: number; error_subcode?: number };
    };
    if (!res.ok) {
      const consentRequired = isConsentRequiredMetaError(data.error);
      console.warn("[lead-magnet] profile fetch failed:", data.error?.message ?? res.status, scopedUserId, {
        consentRequired,
      });
      return {
        username: null,
        name: null,
        status: "unknown",
        isFollower: null,
      };
    }
    const rawFollow = typeof data.is_user_follow_business === "boolean"
      ? data.is_user_follow_business
      : null;
    const status = rawFollow === null
      ? "unknown"
      : resolveFollowStatus(rawFollow, opts);
    console.log("[lead-magnet] profile follow check:", {
      scopedUserId,
      username: data.username ?? null,
      is_user_follow_business: rawFollow,
      follow_status: status,
      messagingWindowOpen: Boolean(opts?.messagingWindowOpen),
    });
    return {
      username: typeof data.username === "string" ? data.username : null,
      name: typeof data.name === "string" ? data.name : null,
      status,
      isFollower: followStatusToLegacyBoolean(status),
    };
  } catch (err) {
    console.warn("[lead-magnet] profile fetch error:", err);
    return { username: null, name: null, status: "unknown", isFollower: null };
  }
}

export async function fetchParticipantProfile(
  scopedUserId: string,
  accessToken: string,
): Promise<FollowCheckResult> {
  return fetchParticipantFollowCheck(scopedUserId, accessToken);
}

export async function fetchCommentText(
  commentId: string,
  accessToken: string,
): Promise<{ text: string | null; username: string | null }> {
  const fields = "text,from,username";
  const url =
    `https://graph.facebook.com/${META_GRAPH_VERSION}/${encodeURIComponent(commentId)}?fields=${fields}`;
  try {
    const res = await fetch(url, {
      headers: { Authorization: `Bearer ${accessToken}` },
    });
    const data = await res.json() as {
      text?: string;
      username?: string;
      from?: { username?: string; name?: string };
      error?: { message?: string };
    };
    if (!res.ok) {
      console.warn("[lead-magnet] comment fetch failed:", data.error?.message ?? res.status);
      return { text: null, username: null };
    }
    const username = data.username ?? data.from?.username ?? null;
    return {
      text: typeof data.text === "string" ? data.text : null,
      username: typeof username === "string" ? username : null,
    };
  } catch (err) {
    console.warn("[lead-magnet] comment fetch error:", err);
    return { text: null, username: null };
  }
}

import {
  isConsentRequiredMetaError,
  needsMessagingConsentRecheck,
  resolveFollowStatus,
  shouldSkipFollowGate,
} from "./followCheckStatus.ts";
import { assertEquals } from "https://deno.land/std@0.224.0/assert/mod.ts";

Deno.test("resolveFollowStatus — true is always follower", () => {
  assertEquals(resolveFollowStatus(true), "follower");
  assertEquals(resolveFollowStatus(true, { messagingWindowOpen: false }), "follower");
});

Deno.test("resolveFollowStatus — false before messaging window is unknown", () => {
  assertEquals(resolveFollowStatus(false), "unknown");
  assertEquals(resolveFollowStatus(false, { messagingWindowOpen: false }), "unknown");
});

Deno.test("resolveFollowStatus — false after messaging window is non_follower", () => {
  assertEquals(resolveFollowStatus(false, { messagingWindowOpen: true }), "non_follower");
});

Deno.test("shouldSkipFollowGate — only when skip enabled and follower", () => {
  const campaign = { skip_follow_gate_if_follower: true };
  assertEquals(shouldSkipFollowGate(campaign, "follower"), true);
  assertEquals(shouldSkipFollowGate(campaign, "non_follower"), false);
  assertEquals(shouldSkipFollowGate(campaign, "unknown"), false);
  assertEquals(shouldSkipFollowGate({ skip_follow_gate_if_follower: false }, "follower"), false);
});

Deno.test("needsMessagingConsentRecheck — IG first contact + skip + not follower", () => {
  const campaign = { skip_follow_gate_if_follower: true };
  const enrollment = {
    platform: "instagram" as const,
    comment_id: "cmt-1",
    private_reply_message_id: null,
  };
  assertEquals(needsMessagingConsentRecheck(enrollment, campaign, "unknown"), true);
  assertEquals(needsMessagingConsentRecheck(enrollment, campaign, "non_follower"), true);
  assertEquals(needsMessagingConsentRecheck(enrollment, campaign, "follower"), false);
  assertEquals(
    needsMessagingConsentRecheck(
      { ...enrollment, private_reply_message_id: "msg-1" },
      campaign,
      "unknown",
    ),
    false,
  );
  assertEquals(
    needsMessagingConsentRecheck(
      { ...enrollment, platform: "facebook" },
      campaign,
      "unknown",
    ),
    false,
  );
});

Deno.test("isConsentRequiredMetaError — detects consent errors", () => {
  assertEquals(isConsentRequiredMetaError({ message: "User consent is required" }), true);
  assertEquals(isConsentRequiredMetaError({ code: 230 }), true);
  assertEquals(isConsentRequiredMetaError({ message: "Other error" }), false);
});
